const charDefs=[
 ['carton','Sydney Carton',[],'A brilliant, self-neglecting barrister whose resemblance to Darnay and love for Lucie give his wasted life a final chosen purpose.',15,true],
 ['darnay','Charles Darnay',['Charles Evrémonde'],'A French aristocrat who renounces his family name and estate but cannot escape the obligations and crimes attached to them.',6,true],
 ['lucie','Lucie Manette',[],'Doctor Manette’s compassionate daughter, the golden thread binding a household across exile, trauma, and revolution.',13,true],
 ['manette','Doctor Alexandre Manette',[],'A physician recalled from eighteen years in the Bastille, whose authority and hidden testimony pull in opposite directions.',8,true],
 ['lorry','Jarvis Lorry',[],'Tellson’s practical and deeply loyal clerk, accustomed to calling devotion business.',34,true],
 ['pross','Miss Pross',[],'Lucie’s fierce English guardian, whose loyalty culminates in a physical stand against Madame Defarge.',1,true],
 ['madame-defarge','Thérèse Defarge',['Madame Defarge'],'A Saint Antoine organizer who encodes condemned names in knitting and refuses every boundary on inherited vengeance.',24,false],
 ['defarge','Ernest Defarge',['Monsieur Defarge'],'A wine-shop keeper and former servant of Manette who leads revolutionary action while retaining traces of pity.',23,true],
 ['jerry','Jerry Cruncher',[],'Tellson’s messenger and porter, publicly respectable by day and a grave-robber by night.',12,true],
 ['young-jerry','Young Jerry Cruncher',[],'Jerry’s observant son, fascinated and unsettled by the gap between his father’s declared and secret trades.',25,true],
 ['mrs-cruncher','Mrs. Cruncher',[],'Jerry’s abused wife, whose private prayer and moral resistance survive his suspicion and threats.','pg-0535m',true],
 ['stryver','C. J. Stryver',[],'An ambitious barrister who turns Carton’s insight into professional success and treats marriage as advancement.',18,true],
 ['barsad','John Barsad',['Solomon Pross'],'A professional spy whose concealed identity and access to the prisons make him vulnerable to Carton’s leverage.','pg-0653m',true],
 ['cly','Roger Cly',[],'A fellow spy whose staged English funeral conceals his later service in revolutionary Paris.',37,true],
 ['marquis','Marquis St. Evrémonde',[],'Darnay’s cruel uncle, treating peasant lives as natural tribute to aristocratic privilege.',20,false],
 ['gabelle','Théophile Gabelle',[],'The Evrémonde estate agent whose endangered appeal draws Darnay back into revolutionary France.',45,true],
 ['road-mender','The Road-Mender',['The Wood-Sawyer'],'A village witness transformed into a revolutionary enthusiast and observer beneath La Force.',21,true],
 ['vengeance','The Vengeance',[],'Madame Defarge’s close companion and an eager public voice of revolutionary punishment.',5,true],
 ['gaspard','Gaspard',[],'A bereaved father who avenges his child’s death by killing the marquis.',2,false],
 ['foulon','Joseph-François Foulon',[],'A hated official whose contempt for starvation returns upon him in revolutionary violence.',19,false],
 ['monseigneur','Monseigneur',[],'A great lord whose ritualized luxury exemplifies the ancien régime’s distance from hunger.',11,true],
 ['jacques-three','Jacques Three',[],'A bloodthirsty revolutionary juryman who presses punishment beyond evidence or mercy.',16,true],
 ['president','President of the Tribunal',[],'The presiding voice of revolutionary justice, converting accusation and applause into sentences.',22,true],
 ['seamstress','The Little Seamstress',[],'A young condemned prisoner who recognizes Carton’s substitution and shares his final journey with quiet courage.',4,false],
 ['little-lucie','Little Lucie',[],'Lucie and Charles’s daughter, carrying the household’s future through flight and bereavement.','pg-0686m',true],
]
